import 'package:material_ui/material_ui.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../core/widgets/glass.dart';
import '../../core/storage/study_store.dart';
import '../app/studygram_app.dart';
import '../stories/story_viewer.dart';
import '../feed/feed_screen.dart';
import '../feed/feed_screen.dart';
import '../accounts/account_switcher.dart';

class ProfileScreen extends ConsumerStatefulWidget {const ProfileScreen({super.key});@override ConsumerState<ProfileScreen> createState()=>_ProfileScreenState();}
class _ProfileScreenState extends ConsumerState<ProfileScreen>{int section=0;
 @override Widget build(BuildContext context){final s=ref.watch(subjectsProvider).firstWhere((s)=>s.id==ref.watch(activeSubjectProvider));final all=StudyStore.postsFor(s.id);final posts=section==0?all:section==1?all.where((p)=>p.saved).toList():all.where((p)=>p.mastered).toList();final tint=Color(s.tint);
 return AmbientBackground(child:SafeArea(child:CustomScrollView(physics:const BouncingScrollPhysics(),slivers:[SliverToBoxAdapter(child:Padding(padding:const EdgeInsets.all(18),child:Row(children:[const Text('Profile',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),const Spacer(),TextButton.icon(onPressed:()=>showAccounts(context,ref),icon:const Icon(Icons.switch_account),label:const Text('Accounts'))]))),SliverToBoxAdapter(child:Padding(padding:const EdgeInsets.fromLTRB(18,10,18,18),child:Row(children:[CircleAvatar(radius:42,backgroundColor:tint.withValues(alpha:.2),child:Icon(Icons.menu_book,size:34,color:tint)),const SizedBox(width:16),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(s.name,style:const TextStyle(fontSize:21,fontWeight:FontWeight.bold)),Text(s.handle,style:TextStyle(color:Colors.white.withValues(alpha:.55))),const SizedBox(height:8),Text(s.bio,style:const TextStyle(fontSize:11))]))]))),SliverToBoxAdapter(child:Glass(padding:const EdgeInsets.all(15),child:Row(mainAxisAlignment:MainAxisAlignment.spaceAround,children:[_stat('Files',all.map((p)=>p.sourceName).toSet().length),_stat('Posts',all.length),_stat('Mastered',all.where((p)=>p.mastered).length)]))),SliverToBoxAdapter(child:Padding(padding:const EdgeInsets.all(16),child:SegmentedButton<int>(segments:const [ButtonSegment(value:0,label:Text('All'),icon:Icon(Icons.grid_view)),ButtonSegment(value:1,label:Text('Saved'),icon:Icon(Icons.bookmark)),ButtonSegment(value:2,label:Text('Mastered'),icon:Icon(Icons.check_circle))],selected:{section},onSelectionChanged:(v)=>setState(()=>section=v.first)))),SliverPadding(padding:const EdgeInsets.symmetric(horizontal:12),sliver:SliverGrid(delegate:SliverChildBuilderDelegate((c,i){final p=posts[i];return GestureDetector(onTap:()=>showPostDetail(context,p,tint),child:Glass(radius:14,padding:const EdgeInsets.all(10),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Expanded(child:Text(p.cards.first,overflow:TextOverflow.fade,maxLines:8,style:const TextStyle(fontSize:12))),const SizedBox(height:8),Text(p.sourceName,maxLines:2,overflow:TextOverflow.ellipsis,style:const TextStyle(fontSize:9,fontWeight:FontWeight.bold)),Row(children:[if(p.saved)const Icon(Icons.bookmark,size:12),if(p.mastered)const Icon(Icons.check_circle,size:12,color:Colors.greenAccent)])])));},childCount:posts.length),gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:3,crossAxisSpacing:7,mainAxisSpacing:7,childAspectRatio:.78))),const SliverToBoxAdapter(child:SizedBox(height:100))])));
 }
 Widget _stat(String title,int value)=>Column(children:[Text('$value',style:const TextStyle(fontSize:18,fontWeight:FontWeight.bold)),Text(title,style:const TextStyle(fontSize:11,color:Colors.white60))]);
}
